"""Lab 11: compares the API-first contract with the code-first specification generated by springdoc.

For every contract schema mapped to a DTO it prints the fields present on only one side and the enum values that
differ. A field that the code returns but the contract does not describe is contract drift (the documentation lies
by omission); a field the contract promises but the code does not have is a broken promise.

  docker run --rm -v "$PWD:/w" -w /w --entrypoint python plantshop/mkdocs:1.6.1-material9.7.6 \
    scripts/openapi_code_first_diff.py docs/api/openapi.yaml docs/lab-11/springdoc-*.json
"""
import json
import sys

import yaml

# contract schema -> springdoc schema name (DTO record class)
MAPPING = {
    "Plant": "PlantResponse",
    "Category": "CategoryResponse",
    "PlantPage": "PagedModelPlantResponse",
    "PageMetadata": "PageMetadata",
    "CreateOrderRequest": "CreateOrderRequest",
    "OrderItemRequest": "OrderItemRequest",
    "Order": "OrderResponse",
    "OrderItem": "OrderItemResponse",
    "OrderTracking": "OrderTrackingResponse",
}


def resolve(spec, schema):
    ref = schema.get("$ref")
    return spec["components"]["schemas"][ref.split("/")[-1]] if ref else schema


def main(contract_path, generated_paths):
    with open(contract_path, encoding="utf-8") as f:
        contract = yaml.safe_load(f)
    generated = {}
    for path in generated_paths:
        with open(path, encoding="utf-8") as f:
            generated.update(json.load(f).get("components", {}).get("schemas", {}))

    drift = 0
    for ours, theirs in MAPPING.items():
        if theirs not in generated:
            print(f"{ours:20} -> {theirs}: not in the springdoc output, skipped")
            continue
        a = contract["components"]["schemas"][ours].get("properties", {})
        b = generated[theirs].get("properties", {})
        only_contract = sorted(set(a) - set(b))
        only_code = sorted(set(b) - set(a))
        enum_diff = []
        for name in sorted(set(a) & set(b)):
            ea = resolve(contract, a[name]).get("enum")
            eb = resolve({"components": {"schemas": generated}}, b[name]).get("enum")
            if ea and eb and sorted(ea) != sorted(eb):
                enum_diff.append(f"{name}: contract {ea} vs code {eb}")
        status = "OK" if not (only_contract or only_code or enum_diff) else "DRIFT"
        drift += status == "DRIFT"
        print(f"{ours:20} -> {theirs:24} fields {len(a):2} / {len(b):2}  {status}")
        for line in ([f"  only in contract: {only_contract}"] if only_contract else []) \
                + ([f"  only in code:     {only_code}"] if only_code else []) + [f"  enum {d}" for d in enum_diff]:
            print(line)
    print(f"RESULT: {'PASS' if drift == 0 else 'FAIL'} - {drift} schema(s) differ")
    return 1 if drift else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1], sys.argv[2:]))
